<?php
declare(strict_types=1); namespace Theobroma\OneC\Import;
final class OrderStatusUpdateService {private const TRANSITIONS=['pending'=>['processing','cancelled'],'on-hold'=>['processing','cancelled'],'failed'=>['processing','cancelled'],'processing'=>['completed','cancelled','refunded'],'completed'=>['refunded']];/** @param list<OrderStatusUpdate> $updates */public function apply(array$updates):ImportResult{$a=$s=$err=0;foreach($updates as$u){$o=wc_get_order($u->orderId);if(!$o instanceof \WC_Order){$s++;continue;}$from=(string)$o->get_status();if($from===$u->status){$s++;continue;}if(!in_array($u->status,self::TRANSITIONS[$from]??[],true)){$s++;continue;}try{$o->update_status($u->status,'Статус получен из 1С через Theobroma 1C',true);$a++;}catch(\Throwable){$err++;}}return new ImportResult($a,$s,0,$err);}}
